// === Tab: mySketch ===
function setup() {
	createCanvas(windowWidth, windowHeight);
	background(0);
	fill('red');
	cells = [];
	for(i=-30;i<=30;i++)
	for(j=-30;j<=30;j++) {
		cells.push({
			x:i,
			y:j,
			z:0
		})
	}
}

function draw()
{
	clear()
	for (o of cells) {
		circle(width/2+o.x*4, height/2+o.y*4, 4, 4)
		o.x += sin(o.z/99)*o.y/39
		o.y += sin(o.z/99)*o.x/39
		o.z += (o.x*o.y)/999
	}
}

